#include <iostream>
#include <utility>
#include <vector>

std::pair<int, int> TwoSum(const std::vector<int>& values, int target);

int main()
{
    int n, target;
    while (std::cin >> n >> target)
    {
        std::vector<int> values(n);
        for (int i = 0; i < n; i++)
        {
            std::cin >> values[i];
        }
        std::pair<int, int> r = TwoSum(values, target);
        std::cout << r.first << " " << r.second << "\n";
    }
    return 0;
}

