"""Random small arrays and targets, so pairs, repeats and misses all occur."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 10)
    values = [rng.randint(-6, 6) for _ in range(n)]
    target = rng.randint(-10, 10)
    return {"name": "%d values, target %d #%d" % (n, target, index),
            "stdin": "%d %d\n%s\n" % (n, target, " ".join(map(str, values)))}
